(function(root){'use strict';const methods={auto:{name:'Авто',rate:2.1,factor:200,min:30,days:'15–22'},rail:{name:'ЖД',rate:1.7,factor:200,min:30,days:'25–35'},air:{name:'Авиа',rate:5.8,factor:167,min:10,days:'5–9'},sea:{name:'Море',rate:.95,factor:200,min:500,days:'40–55'}};function positive(value,name,allowZero=false){const n=Number(value);if(!Number.isFinite(n)||(allowZero?n<0:n<=0))throw new Error('Некорректное поле: '+name);return n}function money(n){return Math.round((n+Number.EPSILON)*100)/100}function boxes(rows){let weight=0,volume=0;if(!rows.length)throw new Error('Добавьте коробку');for(const row of rows){const qty=positive(row.qty,'количество');if(!Number.isInteger(qty))throw new Error('Количество должно быть целым');const w=positive(row.weight,'вес'),l=positive(row.length,'длина'),b=positive(row.width,'ширина'),h=positive(row.height,'высота');weight+=w*qty;volume+=l*b*h*qty/1000000}return {weight,volume}}function calculate(p){const weight=positive(p.weight,'вес'),volume=positive(p.volume,'объём'),rate=positive(p.rate,'ставка'),factor=positive(p.factor,'коэффициент'),min=positive(p.min,'минимум',true),extras=positive(p.extras||0,'расходы',true);const volumetric=volume*factor,billable=Math.max(weight,volumetric,min),freight=money(billable*rate),insurance=p.insurance&&p.value>0&&p.insuranceRate>0?money(positive(p.value,'стоимость')*positive(p.insuranceRate,'страховой тариф')/100):0,total=money(freight+extras+insurance);return {weight,volume,density:weight/volume,volumetric,billable,freight,extras,insurance,total,rub:p.fx>0?money(total*positive(p.fx,'курс')):null,basis:min>Math.max(weight,volumetric)?'minimum':volumetric>weight?'volume':'actual'}}const api={methods,boxes,calculate};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.CargoEngine=api})(typeof window!=='undefined'?window:globalThis);
